<?php ?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lavash N1 • Kuryer Ultra</title><style>:root{--dark:#080d18;--panel:#111a2c;--line:#24314d;--text:#f8fafc;--muted:#94a3b8;--hot:#ff5b00;--hot2:#ffae52;--ok:#22c55e;--red:#ef4444}*{box-sizing:border-box}body{margin:0;font:15px Inter,system-ui;background:linear-gradient(180deg,var(--dark) 0 320px,#f4f7fb 320px);color:#111827}.wrap{max-width:1180px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center;color:#fff;padding:10px 0 16px}.brand{display:flex;align-items:center;gap:11px;font-size:22px;font-weight:1000}.logo{width:48px;height:48px;display:grid;place-items:center;border-radius:16px;background:linear-gradient(135deg,var(--hot),var(--hot2));box-shadow:0 15px 35px #ff5b0040}.online{color:#8ff0b8;font-weight:900}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 5px #22c55e18}.hero{background:linear-gradient(135deg,#111a2c,#1d2a43);border:1px solid #ffffff12;color:#fff;padding:26px;border-radius:28px;box-shadow:0 30px 90px #0006;position:relative;overflow:hidden}.hero:after{content:'🛵';position:absolute;right:35px;top:10px;font-size:100px;opacity:.12;transform:rotate(-8deg)}.hero h1{margin:0;font-size:30px}.hero p{color:#cbd5e1;margin:7px 0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.btn{border:0;border-radius:13px;padding:11px 14px;font-weight:900;cursor:pointer}.primary{background:linear-gradient(135deg,var(--hot),var(--hot2));color:#fff}.dark{background:#111827;color:#fff}.light{background:#fff;color:#344054;border:1px solid #d0d5dd}.danger{background:#fee4e2;color:#b42318}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin:14px 0}.card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:17px;box-shadow:0 18px 50px #11182710}.label{color:#667085;font-weight:800}.metric{font-size:27px;font-weight:1000;margin-top:5px}.orders{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.order{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:17px;box-shadow:0 16px 45px #11182710}.orderHead{display:flex;justify-content:space-between;gap:8px}.orderId{font-weight:1000;font-size:18px}.pill{display:inline-block;border-radius:999px;padding:6px 9px;font-size:11px;font-weight:900;background:#e0f2fe;color:#075985}.meta{display:grid;gap:6px;color:#475467;margin:12px 0}.amount{font-size:21px;font-weight:1000}.map{margin-top:10px;border:1px solid #e5e7eb;border-radius:14px;overflow:hidden}.map iframe{display:block;width:100%;height:190px;border:0}.history{max-height:520px;overflow:auto;display:grid;gap:9px}.historyItem{padding:12px;border:1px solid #e5e7eb;border-radius:14px}.login{min-height:calc(100vh - 36px);display:grid;place-items:center}.loginCard{width:min(450px,100%);background:#fff;border-radius:28px;padding:28px;box-shadow:0 30px 90px #0003}.field{margin:13px 0}.field label{display:block;font-weight:900;margin-bottom:6px}.field input{width:100%;padding:13px;border:1px solid #d0d5dd;border-radius:14px;outline:none}.error{margin-top:10px;background:#fef3f2;border:1px solid #fecdca;color:#b42318;padding:11px;border-radius:13px;font-weight:800}.muted{color:#667085}.empty{text-align:center;padding:30px;color:#667085}@media(max-width:900px){.orders{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){body{background:linear-gradient(180deg,var(--dark) 0 290px,#f4f7fb 290px)}.wrap{padding:12px}.top{align-items:flex-start}.hero{padding:21px}.hero h1{font-size:25px}.hero:after{right:10px;font-size:72px}.grid{grid-template-columns:1fr 1fr}.actions .btn{width:100%}}@media(max-width:430px){.grid{grid-template-columns:1fr}}
</style></head><body><div class="wrap"><header class="top"><div class="brand"><span class="logo">🛵</span><span>Lavash N1<br><small style="font-size:11px;color:#94a3b8">Kuryer Ultra</small></span></div><div id="server" class="online"><span class="dot"></span> Tekshirilmoqda...</div></header><div id="app"></div></div><script>
const API='panel_api.php',KEY='lavash_courier_ultra_2026',app=document.getElementById('app'),server=document.getElementById('server');
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(action,opt={}){const t=localStorage.getItem(KEY)||'';const sep=action.includes('?')?'&':'?';const u=API+'?action='+encodeURIComponent(action)+(t?'&token='+encodeURIComponent(t):'')+'&_='+Date.now();const r=await fetch(u,{...opt,cache:'no-store'});const tx=await r.text();let d;try{d=JSON.parse(tx)}catch{throw Error('Server JSON javob bermadi (HTTP '+r.status+')')}return d}
function login(message=''){app.innerHTML='<div class="login"><div class="loginCard"><div class="brand" style="color:#111827"><span class="logo">🛵</span><span>Lavash N1<br><small style="font-size:11px;color:#667085">Kuryer Ultra</small></span></div><h1 style="margin-bottom:5px">Xush kelibsiz</h1><p class="muted">Kuryer kabinetiga kirish.</p><div class="field"><label>Login</label><input id="u" value="Daler" autocomplete="username"></div><div class="field"><label>Parol</label><input id="p" value="Lavash" type="password" autocomplete="current-password"></div><button id="go" class="btn primary" style="width:100%">Kirish</button><div id="e" class="error" style="display:'+(message?'block':'none')+'">'+esc(message)+'</div></div></div>';document.getElementById('go').onclick=doLogin}
async function doLogin(){const b=document.getElementById('go'),e=document.getElementById('e');b.disabled=true;b.textContent='Ulanmoqda...';e.style.display='none';try{const f=new FormData();f.append('login',document.getElementById('u').value.trim());f.append('password',document.getElementById('p').value);const d=await api('courier_login',{method:'POST',body:f});if(!d.ok)throw Error(d.message||'Login yoki parol noto‘g‘ri');localStorage.setItem(KEY,d.token);render()}catch(x){e.textContent=x.message;e.style.display='block'}finally{b.disabled=false;b.textContent='Kirish'}}
function map(x){const a=Number(x.lat),b=Number(x.lng);if(!Number.isFinite(a)||!Number.isFinite(b))return '<div class="muted">📍 Lokatsiya tasdiqlanmagan</div>';const q=encodeURIComponent(a+','+b);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><div class="actions"><a class="btn dark" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Google Maps’da yo‘l</a></div>'}
async function render(){try{const m=await api('courier_me');if(!m.ok){localStorage.removeItem(KEY);login(m.message||'Kirish kerak.');return}const [s,o,h]=await Promise.all([api('courier_summary'),api('courier_orders'),api('courier_history')]);if(!s.ok||!o.ok||!h.ok)throw Error((!s.ok&&s.message)||(!o.ok&&o.message)||(!h.ok&&h.message)||'Ma’lumotlarni yuklashda xato');const d=s.data||{},orders=o.data||[],history=h.data||[];server.innerHTML='<span class="dot"></span> ONLINE • serverga ulangan';app.innerHTML='<div class="hero"><h1>Salom, '+esc(m.data?.name||'Daler Lavash')+' 👋</h1><p>Bugungi ish davri: '+esc(d.business_start||'06:00')+' → '+esc(d.business_end||'00:00')+'</p><div class="actions"><button class="btn primary" onclick="render()">↻ Yangilash</button><button class="btn light" onclick="logout()">Chiqish</button></div></div><div class="grid"><div class="card"><div class="label">Faol buyurtmalar</div><div class="metric">'+orders.length+'</div></div><div class="card"><div class="label">Bugungi savdo</div><div class="metric">'+Number(d.sales||0).toLocaleString('uz-UZ')+' so‘m</div></div><div class="card"><div class="label">Yetkazilgan</div><div class="metric">'+d.completed+'</div></div><div class="card"><div class="label">Ish vaqti</div><div class="metric">06:00–00:00</div></div></div><div style="display:flex;justify-content:space-between;align-items:center;margin:18px 0 10px"><h2 style="margin:0">🛵 Faol buyurtmalar</h2><span class="muted">'+orders.length+' ta</span></div><div class="orders">'+(orders.map(x=>'<article class="order"><div class="orderHead"><div class="orderId">#'+x.id+' • '+esc(x.customer_name)+'</div><span class="pill">'+esc(x.status)+'</span></div><div class="meta"><div>📞 <a href="tel:'+esc(x.phone||'')+'">'+esc(x.phone||'')+'</a></div><div>📍 '+esc(x.address||'Manzil yo‘q')+'</div><div>'+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</div><div class="amount">💰 '+Number(x.amount||0).toLocaleString('uz-UZ')+' so‘m</div></div>'+map(x)+'<div class="actions"><button class="btn primary" onclick="st('+x.id+',\'delivering\')">🛵 Yo‘lga chiqish</button><button class="btn dark" onclick="st('+x.id+',\'completed\')">✅ Yetkazildi</button></div></article>').join('')||'<div class="card empty">Sizga biriktirilgan faol buyurtma yo‘q.</div>')+'</div><div style="margin:22px 0 10px"><h2>🧾 Buyurtma tarixi</h2></div><div class="card history">'+(history.map(x=>'<div class="historyItem"><b>#'+x.id+' • '+esc(x.customer_name)+'</b><br><span class="muted">'+new Date(x.created_at).toLocaleString('uz-UZ')+' • '+esc(x.status)+'</span><br>'+Number(x.amount||0).toLocaleString('uz-UZ')+' so‘m • '+(((x.payment_method||'cash')==='card')?'Karta':'Naqd')+'</div>').join('')||'<div class="empty">Tarix bo‘sh.</div>')+'</div>'}catch(e){server.innerHTML='<span style="color:#fda29b">● Ulanish muammosi</span>';app.innerHTML='<div class="card error"><b>Kuryer panel yuklanmadi.</b><br>'+esc(e.message)+'<br><br><button class="btn primary" onclick="render()">↻ Qayta urinish</button></div>'}}
async function st(id,s){try{const f=new FormData();f.append('order_id',id);f.append('status',s);const d=await api('courier_status',{method:'POST',body:f});if(!d.ok)throw Error(d.message||'Status saqlanmadi');render()}catch(e){alert(e.message)}}
async function logout(){localStorage.removeItem(KEY);login()}
(async()=>{try{const h=await api('health');server.innerHTML=h.database?'<span class="dot"></span> ONLINE • server + baza':'<span style="color:#fdb022">● Server online • baza kutilyapti</span>'}catch{server.innerHTML='<span style="color:#fda29b">● Server ulanmagan</span>'}localStorage.getItem(KEY)?render():login()})();setInterval(()=>{if(localStorage.getItem(KEY))render()},15000);
</script></body></html>
